import type { HTMLArkProps } from '@ark-ui/solid/factory';
import { ark } from '@ark-ui/solid/factory';
import {
  Select as SelectPrimitive,
  type CollectionItem,
  type SelectRootProps as ArkSelectRootProps,
  type SelectRootProviderProps as ArkSelectRootProviderProps,
  useSelect,
  useSelectContext,
  useSelectItemContext,
} from '@ark-ui/solid/select';
import { clsx } from 'clsx';
import type { ComponentProps, JSX } from 'solid-js';
import { children, splitProps } from 'solid-js';
import { a11yLabels } from '@/lib/moduix/a11yLabels';
import { CheckIcon, ChevronUpDownIcon } from '@/lib/moduix/icons/ui';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import { CloseButton } from '../close-button';
import styles from './Select.module.css';

type SelectRootProps<T extends CollectionItem> = ArkSelectRootProps<T> & OverlayPortalProps;
type SelectRootProviderProps<T extends CollectionItem> = ArkSelectRootProviderProps<T> &
  OverlayPortalProps;
type SelectFieldProps = Omit<
  ComponentProps<typeof SelectPrimitive.Control>,
  'asChild' | 'children'
> & {
  clearLabel?: string;
  indicator?: JSX.Element;
  placeholder?: ComponentProps<typeof SelectPrimitive.ValueText>['placeholder'];
};

function Select<T extends CollectionItem>(props: SelectRootProps<T>) {
  const [local, others] = splitProps(props, [
    'class',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <SelectPrimitive.Root
        class={clsx(styles.root, local.class)}
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
        data-slot="select-root"
      />
    </OverlayPortalProvider>
  );
}

function SelectRootProvider<T extends CollectionItem>(props: SelectRootProviderProps<T>) {
  const [local, others] = splitProps(props, [
    'class',
    'lazyMount',
    'portalled',
    'portalRef',
    'unmountOnExit',
  ]);

  return (
    <OverlayPortalProvider portalled={local.portalled} portalRef={local.portalRef}>
      <SelectPrimitive.RootProvider
        class={clsx(styles.root, local.class)}
        lazyMount={local.lazyMount ?? true}
        unmountOnExit={local.unmountOnExit ?? true}
        {...others}
        data-slot="select-root-provider"
      />
    </OverlayPortalProvider>
  );
}

function SelectLabel(props: ComponentProps<typeof SelectPrimitive.Label>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.Label
      class={clsx(styles.label, local.class)}
      {...others}
      data-slot="select-label"
    />
  );
}

function SelectControl(props: ComponentProps<typeof SelectPrimitive.Control>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.Control
      class={clsx(styles.control, local.class)}
      {...others}
      data-slot="select-control"
    />
  );
}

function SelectTrigger(props: ComponentProps<typeof SelectPrimitive.Trigger>) {
  const [local, others] = splitProps(props, ['asChild', 'class']);

  return (
    <SelectPrimitive.Trigger
      asChild={local.asChild}
      class={clsx(!local.asChild && styles.trigger, local.class)}
      {...others}
      data-slot="select-trigger"
    />
  );
}

function SelectValueText(props: ComponentProps<typeof SelectPrimitive.ValueText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.ValueText
      class={clsx(styles.valueText, local.class)}
      {...others}
      data-slot="select-value-text"
    />
  );
}

function SelectClearTrigger(props: ComponentProps<typeof SelectPrimitive.ClearTrigger>) {
  const [local, others] = splitProps(props, [
    'aria-label',
    'aria-labelledby',
    'asChild',
    'children',
    'class',
  ]);
  const triggerClass = () => clsx(styles.clearTrigger, local.class);

  if (local.asChild) {
    return (
      <SelectPrimitive.ClearTrigger
        asChild={local.asChild}
        aria-label={local['aria-label']}
        aria-labelledby={local['aria-labelledby']}
        class={triggerClass()}
        {...others}
        data-slot="select-clear-trigger"
      >
        {local.children}
      </SelectPrimitive.ClearTrigger>
    );
  }

  return (
    <SelectPrimitive.ClearTrigger
      asChild={(triggerProps) => {
        const resolvedProps = triggerProps();

        return (
          <CloseButton
            {...resolvedProps}
            aria-label={
              local['aria-label'] ??
              (local['aria-labelledby'] == null ? a11yLabels.clearSelection : undefined)
            }
            aria-labelledby={local['aria-labelledby']}
          >
            {local.children}
          </CloseButton>
        );
      }}
      class={triggerClass()}
      {...others}
      data-slot="select-clear-trigger"
    />
  );
}

function SelectIndicator(props: ComponentProps<typeof SelectPrimitive.Indicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <SelectPrimitive.Indicator
      class={clsx(styles.indicator, local.class)}
      {...others}
      data-slot="select-indicator"
    >
      {resolvedChildren() ?? <ChevronUpDownIcon />}
    </SelectPrimitive.Indicator>
  );
}

function SelectField(props: SelectFieldProps) {
  const [local, others] = splitProps(props, ['clearLabel', 'indicator', 'placeholder']);

  return (
    <SelectControl {...others}>
      <SelectTrigger>
        <SelectValueText placeholder={local.placeholder} />
      </SelectTrigger>
      {local.clearLabel && <SelectClearTrigger aria-label={local.clearLabel} />}
      <SelectIndicator>{local.indicator}</SelectIndicator>
    </SelectControl>
  );
}

function SelectPositioner(props: ComponentProps<typeof SelectPrimitive.Positioner>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <OverlayPortal>
      <SelectPrimitive.Positioner
        class={clsx(styles.positioner, local.class)}
        {...others}
        data-slot="select-positioner"
      />
    </OverlayPortal>
  );
}

function SelectContent(props: ComponentProps<typeof SelectPrimitive.Content>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.Content
      class={clsx(styles.content, local.class)}
      {...others}
      data-slot="select-content"
    />
  );
}

function SelectList(props: ComponentProps<typeof SelectPrimitive.List>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.List
      class={clsx(styles.list, local.class)}
      {...others}
      data-slot="select-list"
    />
  );
}

function SelectItemGroup(props: ComponentProps<typeof SelectPrimitive.ItemGroup>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.ItemGroup
      class={clsx(styles.itemGroup, local.class)}
      {...others}
      data-slot="select-item-group"
    />
  );
}

function SelectItemGroupLabel(props: ComponentProps<typeof SelectPrimitive.ItemGroupLabel>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.ItemGroupLabel
      class={clsx(styles.itemGroupLabel, local.class)}
      {...others}
      data-slot="select-item-group-label"
    />
  );
}

function SelectItem(props: ComponentProps<typeof SelectPrimitive.Item>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.Item
      class={clsx(styles.item, local.class)}
      {...others}
      data-slot="select-item"
    />
  );
}

function SelectItemText(props: ComponentProps<typeof SelectPrimitive.ItemText>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <SelectPrimitive.ItemText
      class={clsx(styles.itemText, local.class)}
      {...others}
      data-slot="select-item-text"
    />
  );
}

function SelectItemIndicator(props: ComponentProps<typeof SelectPrimitive.ItemIndicator>) {
  const [local, others] = splitProps(props, ['children', 'class']);
  const resolvedChildren = children(() => local.children);

  return (
    <SelectPrimitive.ItemIndicator
      class={clsx(styles.itemIndicator, local.class)}
      {...others}
      data-slot="select-item-indicator"
    >
      {resolvedChildren() ?? <CheckIcon />}
    </SelectPrimitive.ItemIndicator>
  );
}

type SelectOptionProps = Omit<
  ComponentProps<typeof SelectPrimitive.Item>,
  'asChild' | 'children'
> & {
  children: JSX.Element;
  indicator?: JSX.Element | false;
};

function SelectOption(props: SelectOptionProps) {
  const [local, others] = splitProps(props, ['children', 'indicator']);

  return (
    <SelectItem {...others}>
      <SelectItemText>{local.children}</SelectItemText>
      {local.indicator !== false && <SelectItemIndicator>{local.indicator}</SelectItemIndicator>}
    </SelectItem>
  );
}

function SelectItemTextContent(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      class={clsx(styles.itemTextContent, local.class)}
      {...others}
      data-slot="select-item-text-content"
    />
  );
}

function SelectItemTextIcon(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      class={clsx(styles.itemTextIcon, local.class)}
      {...others}
      data-slot="select-item-text-icon"
    />
  );
}

function SelectItemTextLabel(props: HTMLArkProps<'span'>) {
  const [local, others] = splitProps(props, ['class']);

  return (
    <ark.span
      class={clsx(styles.itemTextLabel, local.class)}
      {...others}
      data-slot="select-item-text-label"
    />
  );
}

const SelectContext = SelectPrimitive.Context;
const SelectHiddenSelect = SelectPrimitive.HiddenSelect;
const SelectItemContext = SelectPrimitive.ItemContext;

export {
  Select,
  SelectClearTrigger,
  SelectContext,
  SelectControl,
  SelectContent,
  SelectField,
  SelectHiddenSelect,
  SelectIndicator,
  SelectItem,
  SelectItemContext,
  SelectItemGroup,
  SelectItemGroupLabel,
  SelectItemIndicator,
  SelectItemText,
  SelectItemTextContent,
  SelectItemTextIcon,
  SelectItemTextLabel,
  SelectLabel,
  SelectList,
  SelectOption,
  SelectPositioner,
  SelectRootProvider,
  SelectTrigger,
  SelectValueText,
  useSelect,
  useSelectContext,
  useSelectItemContext,
};

export type { SelectFieldProps, SelectOptionProps, SelectRootProps, SelectRootProviderProps };

export type {
  SelectClearTriggerProps,
  SelectContentProps,
  SelectContextProps,
  SelectControlProps,
  SelectHiddenSelectProps,
  SelectHighlightChangeDetails,
  SelectIndicatorProps,
  SelectItemContextProps,
  SelectItemGroupLabelProps,
  SelectItemGroupProps,
  SelectItemIndicatorProps,
  SelectItemProps,
  SelectItemTextProps,
  SelectLabelProps,
  SelectListProps,
  SelectOpenChangeDetails,
  SelectPositionerProps,
  SelectTriggerProps,
  SelectValueChangeDetails,
  SelectValueTextProps,
  UseSelectContext,
  UseSelectItemContext,
  UseSelectProps,
  UseSelectReturn,
} from '@ark-ui/solid/select';

@layer moduix.components {
  .root {
    box-sizing: border-box;
    display: flex;
    width: var(--moduix-select-width, 14rem);
    max-width: 100%;
    min-width: 0;
    flex-direction: column;
    gap: var(--moduix-spacing-1-5);
    color: var(--moduix-color-foreground);
  }

  .label {
    display: inline-flex;
    align-items: center;
    font-size: var(--moduix-text-sm);
    font-weight: var(--moduix-weight-medium);
    line-height: var(--moduix-line-height-text-sm);
    user-select: none;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .control {
    --_select-action-size: var(--moduix-select-action-size, var(--moduix-size-xs));
    --_select-action-offset: var(--moduix-spacing-2);

    position: relative;
    display: flex;
    width: 100%;
    min-width: 0;
    align-items: center;

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
    }
  }

  .trigger {
    box-sizing: border-box;
    display: inline-flex;
    width: 100%;
    min-width: 0;
    height: var(--moduix-select-control-height, var(--moduix-size-md));
    align-items: center;
    margin: 0;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-select-radius, var(--moduix-radius-md));
    padding-inline: var(--moduix-spacing-3-5)
      calc(var(--_select-action-offset) + var(--_select-action-size) + var(--moduix-spacing-3-5));
    background-color: var(--moduix-color-background);
    color: inherit;
    font: inherit;
    text-align: start;
    outline: var(--moduix-focus-ring-inset-width) solid transparent;
    outline-offset: var(--moduix-focus-ring-inset-offset);
    cursor: pointer;
    user-select: none;
    transition:
      border-color var(--moduix-transition-default),
      outline-color var(--moduix-transition-default);

    &[data-placeholder-shown] {
      color: var(--moduix-color-muted-foreground);
    }

    /* Reserve room for the clear action too; the text keeps a 10px gap before it. */
    .control:has(> .clearTrigger:not([hidden])) > & {
      padding-inline-end: calc(
        var(--_select-action-offset) + var(--_select-action-size) * 2 + var(--moduix-spacing-0-5) +
          var(--moduix-spacing-2-5)
      );
    }

    &:disabled {
      cursor: default;
    }

    &[data-state='open'],
    &:focus-visible {
      border-color: var(--moduix-color-ring);
      outline-color: var(--moduix-color-ring);
    }

    .control[data-invalid] & {
      border-color: var(--moduix-color-destructive);
      outline-color: var(--moduix-color-destructive);
    }
  }

  .valueText,
  .itemText {
    min-width: 0;
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .indicator,
  .clearTrigger {
    position: absolute;
    top: 50%;
    inset-inline-end: var(--_select-action-offset);
    transform: translateY(-50%);
  }

  .indicator {
    display: inline-flex;
    width: var(--_select-action-size);
    height: var(--_select-action-size);
    align-items: center;
    justify-content: center;
    border-radius: var(--moduix-radius-sm);
    color: var(--moduix-color-muted-foreground);
    pointer-events: none;
    transition:
      background-color var(--moduix-transition-default),
      color var(--moduix-transition-default);

    & > svg {
      width: var(--moduix-spacing-4);
      height: var(--moduix-spacing-4);
    }

    .trigger:enabled:hover ~ & {
      @media (hover: hover) {
        background-color: var(--moduix-color-muted);
        color: var(--moduix-color-foreground);
      }
    }
  }

  .clearTrigger {
    --moduix-close-button-size: var(--_select-action-size);

    inset-inline-end: calc(
      var(--_select-action-offset) + var(--_select-action-size) + var(--moduix-spacing-0-5)
    );
  }

  .positioner {
    z-index: var(--z-index);
  }

  .content {
    box-sizing: border-box;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    display: flex;
    min-width: var(--reference-width);
    max-width: var(--available-width);
    max-height: min(var(--moduix-select-content-max-height, 24rem), var(--available-height));
    flex-direction: column;
    overflow: auto;
    border: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-radius: var(--moduix-select-radius, var(--moduix-radius-md));
    padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
    background-color: var(--moduix-color-popover);
    box-shadow: var(--moduix-shadow-lg);
    color: var(--moduix-color-popover-foreground);
    transform-origin: var(--transform-origin);
    outline: 0;
    overscroll-behavior: contain;
    scroll-padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
      pointer-events: none;
    }
  }

  /* Scrolls on its own, so a search field above the list stays in view. */
  .list {
    display: flex;
    min-height: 0;
    flex-direction: column;
    overflow-y: auto;
    outline: 0;
    overscroll-behavior: contain;
    scroll-padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
  }

  .itemGroup {
    display: flex;
    flex-direction: column;

    & + & {
      margin-block-start: var(--moduix-spacing-2);
    }
  }

  .itemGroupLabel {
    padding-block: var(--moduix-popup-group-label-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-spacing-2-5);
    color: var(--moduix-popup-group-label-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-popup-group-label-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-popup-group-label-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-popup-group-label-line-height, var(--moduix-line-height-text-xs));
  }

  .item {
    box-sizing: border-box;
    position: relative;
    display: flex;
    min-height: var(--moduix-popup-item-min-height, var(--moduix-size-sm));
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-spacing-2);
    margin-inline: var(--moduix-spacing-1);
    border-radius: var(--moduix-radius-sm);
    padding-block: var(--moduix-popup-item-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3));
    font-size: var(--moduix-popup-item-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-popup-item-line-height, var(--moduix-line-height-text-sm));
    outline: 0;
    cursor: default;
    user-select: none;

    &[data-highlighted] {
      background-color: var(--moduix-color-accent);
      color: var(--moduix-color-accent-foreground);
    }

    &[data-disabled] {
      opacity: var(--moduix-opacity-disabled);
      pointer-events: none;
    }
  }

  .itemIndicator {
    display: inline-flex;
    width: var(--moduix-spacing-3-5);
    height: var(--moduix-spacing-3-5);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;

    & > svg {
      width: var(--moduix-spacing-3);
      height: var(--moduix-spacing-3);
    }
  }

  .itemTextContent {
    display: inline-flex;
    max-width: 100%;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-spacing-2);
    vertical-align: top;
  }

  .itemTextIcon {
    display: inline-flex;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }

  .itemTextLabel {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  @media (prefers-reduced-motion: reduce) {
    .content[data-state] {
      animation: none;
    }
  }
}
